import type { Plugin, PluginListenerHandle } from '@capacitor/core';

/**
 * Result returned by `analyze()`.
 */
export interface AnalysisResult {
  count: number;
  sum: number;
  mean: number;
  min: number;
  max: number;
  stdDev: number;
}

/**
 * Options accepted by `analyze()`.
 */
export interface AnalyzeOptions {
  values: number[];
}

/**
 * Result returned by `getRunningTotal()`.
 */
export interface RunningTotalResult {
  total: number;
}

/**
 * Payload emitted with every `analysisComplete` event.
 */
export interface AnalysisCompleteEvent {
  sequence: number;
  mean: number;
}

/**
 * Definitions interface for the MetricsAnalyzer plugin.
 *
 * Extending `Plugin` provides `addListener` / `removeAllListeners`
 * with proper typing, and we add a typed convenience listener for
 * the `analysisComplete` event.
 */
export interface MetricsAnalyzerPlugin extends Plugin {
  analyze(options: AnalyzeOptions): Promise<AnalysisResult>;
  getRunningTotal(): Promise<RunningTotalResult>;

  /**
   * Typed listener for the `analysisComplete` event.
   */
  addListener(
    eventName: 'analysisComplete',
    listenerFunc: (event: AnalysisCompleteEvent) => void,
  ): Promise<PluginListenerHandle>;
}

import { WebPlugin } from '@capacitor/core';
import type {
  AnalysisCompleteEvent,
  AnalysisResult,
  AnalyzeOptions,
  MetricsAnalyzerPlugin,
  RunningTotalResult,
} from './definitions';

/**
 * Web implementation of the MetricsAnalyzer plugin.
 *
 * Computes summary statistics for an array of numbers and emits an
 * `analysisComplete` event every time `analyze` is invoked.
 */
export class MetricsAnalyzerWeb
  extends WebPlugin
  implements MetricsAnalyzerPlugin
{
  /** Number of analyses performed since the page loaded. */
  private runningTotal = 0;

  async analyze(options: AnalyzeOptions): Promise<AnalysisResult> {
    const values = options?.values ?? [];
    this.runningTotal += 1;
    const sequence = this.runningTotal;

    const count = values.length;
    if (count === 0) {
      const emptyResult: AnalysisResult = {
        count: 0,
        sum: 0,
        mean: 0,
        min: 0,
        max: 0,
        stdDev: 0,
      };

      this.notifyListeners('analysisComplete', {
        sequence,
        mean: 0,
      } satisfies AnalysisCompleteEvent);

      return emptyResult;
    }

    let sum = 0;
    let min = values[0];
    let max = values[0];
    for (const v of values) {
      sum += v;
      if (v < min) min = v;
      if (v > max) max = v;
    }

    const mean = sum / count;

    // Population standard deviation: divide by N (not N-1).
    let squaredDeviations = 0;
    for (const v of values) {
      const diff = v - mean;
      squaredDeviations += diff * diff;
    }
    const stdDev = Math.sqrt(squaredDeviations / count);

    const result: AnalysisResult = {
      count,
      sum,
      mean,
      min,
      max,
      stdDev,
    };

    this.notifyListeners('analysisComplete', {
      sequence,
      mean,
    } satisfies AnalysisCompleteEvent);

    return result;
  }

  async getRunningTotal(): Promise<RunningTotalResult> {
    return { total: this.runningTotal };
  }
}

import { registerPlugin } from '@capacitor/core';
import type { MetricsAnalyzerPlugin } from './definitions';

/**
 * Register the MetricsAnalyzer plugin with Capacitor, supplying the
 * web implementation via a lazy dynamic import.
 */
export const MetricsAnalyzer = registerPlugin<MetricsAnalyzerPlugin>(
  'MetricsAnalyzer',
  {
    web: () => import('./web').then((m) => new m.MetricsAnalyzerWeb()),
  },
);

export type {
  AnalysisCompleteEvent,
  AnalysisResult,
  AnalyzeOptions,
  MetricsAnalyzerPlugin,
  RunningTotalResult,
} from './definitions';
export { MetricsAnalyzerWeb } from './web';

import { MetricsAnalyzer } from './plugin';
import type { AnalysisCompleteEvent } from './plugin';

// Expose the plugin instance so a headless browser can drive it.
declare global {
  interface Window {
    MetricsAnalyzer: typeof MetricsAnalyzer;
    __analysisEvents: AnalysisCompleteEvent[];
  }
}

window.MetricsAnalyzer = MetricsAnalyzer;
window.__analysisEvents = [];

// Register an `analysisComplete` listener when the page loads so that
// every emitted event is captured and rendered into the DOM.
MetricsAnalyzer.addListener('analysisComplete', (event) => {
  window.__analysisEvents.push(event);

  const eventCountEl = document.getElementById('event-count');
  if (eventCountEl) {
    eventCountEl.textContent = String(window.__analysisEvents.length);
  }
});

/**
 * Render the most recent analysis result as JSON text into the result element.
 */
export function renderResult(result: unknown): void {
  const resultEl = document.getElementById('result');
  if (resultEl) {
    resultEl.textContent = JSON.stringify(result, null, 2);
  }
}

// Run a small self-test on load so the page shows something meaningful
// even before being driven by an external script.
window.addEventListener('DOMContentLoaded', async () => {
  try {
    const result = await MetricsAnalyzer.analyze({ values: [2, 4, 4, 4, 5, 5, 7, 9] });
    renderResult(result);
  } catch {
    // Intentionally ignored: external scripts will call analyze() directly.
  }
});

